  ```
  {
      "household": {
      "income": 52000,
      "people": [
        {
            "dob": "1992-01-01",
            "aptc_eligible": true,
         "gender": "Female",
          "uses_tobacco": false
         }
       ]
      },
      "market": "Individual",
